def transform(grid):
    h,w=len(grid),len(grid[0])
    colors={v for row in grid for v in row if v not in (0,1)}
    color=next(iter(colors))
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
    minr=min(r for r,c in pts); maxr=max(r for r,c in pts)
    minc=min(c for r,c in pts); maxc=max(c for r,c in pts)
    shape={(r-minr,c-minc) for r,c in pts}
    out=[row[:] for row in grid]
    for dr in range(h-(maxr-minr+1)+1):
      for dc in range(w-(maxc-minc+1)+1):
        cells=[(dr+r,dc+c) for r,c in shape]
        if all(grid[r][c]==0 for r,c in cells):
          for r,c in cells: out[r][c]=color
    return out
